[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "user-profile-doc",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "user-profile-doc",
      "components": [
        {
          "id": "root",
          "type": "Column",
          "properties": {
            "children": [
              {
                "id": "title",
                "type": "Text",
                "properties": {
                  "text": "User Profile JSON Documentation",
                  "style": "title"
                }
              },
              {
                "id": "description",
                "type": "Text",
                "properties": {
                  "text": "This table describes the keys found in the provided user profile JSON object, including their data types and purpose."
                }
              },
              {
                "id": "table_title",
                "type": "Text",
                "properties": {
                  "text": "Technical Documentation Table:",
                  "style": "heading"
                }
              },
              {
                "id": "doc_table",
                "type": "Table",
                "properties": {
                  "children": [
                    {
                      "id": "table_header",
                      "type": "TableHeader",
                      "properties": {
                        "children": [
                          {
                            "id": "header_key",
                            "type": "Text",
                            "properties": {
                              "text": "Key",
                              "style": "label"
                            }
                          },
                          {
                            "id": "header_type",
                            "type": "Text",
                            "properties": {
                              "text": "Data Type",
                              "style": "label"
                            }
                          },
                          {
                            "id": "header_desc",
                            "type": "Text",
                            "properties": {
                              "text": "Description",
                              "style": "label"
                            }
                          }
                        ]
                      }
                    },
                    {
                      "id": "row_id",
                      "type": "TableRow",
                      "properties": {
                        "children": [
                          {
                            "id": "key_id",
                            "type": "Text",
                            "properties": {
                              "text": "id"
                            }
                          },
                          {
                            "id": "type_id",
                            "type": "Text",
                            "properties": {
                              "text": "Number (Integer)"
                            }
                          },
                          {
                            "id": "desc_id",
                            "type": "Text",
                            "properties": {
                              "text": "A unique identifier for the user."
                            }
                          }
                        ]
                      }
                    },
                    {
                      "id": "row_name",
                      "type": "TableRow",
                      "properties": {
                        "children": [
                          {
                            "id": "key_name",
                            "type": "Text",
                            "properties": {
                              "text": "name"
                            }
                          },
                          {
                            "id": "type_name",
                            "type": "Text",
                            "properties": {
                              "text": "String"
                            }
                          },
                          {
                            "id": "desc_name",
                            "type": "Text",
                            "properties": {
                              "text": "The full name of the user."
                            }
                          }
                        ]
                      }
                    },
                    {
                      "id": "row_roles",
                      "type": "TableRow",
                      "properties": {
                        "children": [
                          {
                            "id": "key_roles",
                            "type": "Text",
                            "properties": {
                              "text": "roles"
                            }
                          },
                          {
                            "id": "type_roles",
                            "type": "Text",
                            "properties": {
                              "text": "Array of Strings"
                            }
                          },
                          {
                            "id": "desc_roles",
                            "type": "Text",
                            "properties": {
                              "text": "A list of roles or permissions assigned to the user."
                            }
                          }
                        ]
                      }
                    },
                    {
                      "id": "row_last_login",
                      "type": "TableRow",
                      "properties": {
                        "children": [
                          {
                            "id": "key_last_login",
                            "type": "Text",
                            "properties": {
                              "text": "last_login"
                            }
                          },
                          {
                            "id": "type_last_login",
                            "type": "Text",
                            "properties": {
                              "text": "String (ISO 8601)"
                            }
                          },
                          {
                            "id": "desc_last_login",
                            "type": "Text",
                            "properties": {
                              "text": "The timestamp of the user's last successful login."
                            }
                          }
                        ]
                      }
                    },
                    {
                      "id": "row_settings",
                      "type": "TableRow",
                      "properties": {
                        "children": [
                          {
                            "id": "key_settings",
                            "type": "Text",
                            "properties": {
                              "text": "settings"
                            }
                          },
                          {
                            "id": "type_settings",
                            "type": "Text",
                            "properties": {
                              "text": "Object"
                            }
                          },
                          {
                            "id": "desc_settings",
                            "type": "Text",
                            "properties": {
                              "text": "An object containing user-specific preferences and settings."
                            }
                          }
                        ]
                      }
                    },
                    {
                      "id": "row_theme",
                      "type": "TableRow",
                      "properties": {
                        "children": [
                          {
                            "id": "key_theme",
                            "type": "Text",
                            "properties": {
                              "text": "settings.theme"
                            }
                          },
                          {
                            "id": "type_theme",
                            "type": "Text",
                            "properties": {
                              "text": "String"
                            }
                          },
                          {
                            "id": "desc_theme",
                            "type": "Text",
                            "properties": {
                              "text": "The visual theme preference for the user interface (e.g., \"dark\", \"light\")."
                            }
                          }
                        ]
                      }
                    },
                    {
                      "id": "row_notifications",
                      "type": "TableRow",
                      "properties": {
                        "children": [
                          {
                            "id": "key_notifications",
                            "type": "Text",
                            "properties": {
                              "text": "settings.notifications"
                            }
                          },
                          {
                            "id": "type_notifications",
                            "type": "Text",
                            "properties": {
                              "text": "Boolean"
                            }
                          },
                          {
                            "id": "desc_notifications",
                            "type": "Text",
                            "properties": {
                              "text": "Indicates whether the user has enabled or disabled notifications."
                            }
                          }
                        ]
                      }
                    }
                  ]
                }
              }
            ]
          }
        }
      ]
    }
  }
]
